"""Cuaderno del estudiante, 2.º medio Lengua y Literatura, OA 12 (escritura creativa y flexible en nuevos géneros).

Todos los textos, personas, lugares y cifras son inventados («de ejemplo»); cada ejercicio trae escritos los textos y datos que necesita.
Nota: los títulos de las clases del repositorio son genéricos («Reconocer género, propósito y audiencia», «Investigar y seleccionar insumos»,
«Planificar decisiones», «Escribir un primer desarrollo», «Revisar con evidencia de lectura», «Editar, publicar y justificar»); este cuaderno los sigue.
"""
from __future__ import annotations

from student_lessons import arith, ex, register

OA12 = "LE2M OA 12"
E = ex

MAT = "Este cuaderno, lápiz y los textos y datos escritos en cada ejercicio. No necesitas libros especiales ni internet."


def task(statement, example, criteria, evidence, errors, feedback):
    return {"statement": statement, "example": example, "criteria": criteria, "evidence": evidence, "errors": errors, "feedback": feedback}


def L(oa, n, use, prior, explain, vocab, worked, mistakes, tiers, ctx, sc, open_task, reinforce, extend, materials=MAT):
    register(
        oa, n, materials=materials, use=use, prior=prior, explain=explain, vocab=vocab,
        worked=[{"title": t, "problem": p, "steps": s, "answer": a} for t, p, s, a in worked],
        mistakes=[{"wrong": w, "why": y, "fix": f} for w, y, f in mistakes],
        tiers=dict(zip(("recovery", "understand", "apply", "reason", "challenge"), tiers)),
        context=ctx, selfcheck=sc, open_task=task(*open_task), reinforce=reinforce, extend=extend,
    )


def AB(q, a, b, why):
    """Pregunta de dos alternativas; la correcta se escribe primero (el registro la reubica)."""
    return E(f"{q} A) {a} B) {b}", f"A) {a}", why)


def ABC(q, a, b, c, why):
    """Pregunta de tres alternativas; la correcta se escribe primero (el registro la reubica)."""
    return E(f"{q} A) {a} B) {b} C) {c}", f"A) {a}", why)


